package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_nextElementSibling_TriageGen0Test {

    @Test
    public void testNextElementSibling_MiddleElement() {
        Document doc = Parser.parseBodyFragment("<div><p>1</p><p>2</p><p>3</p></div>");
        Element p1 = doc.select("p").get(0);
        Element p2 = doc.select("p").get(1);
        Element p3 = doc.select("p").get(2);

        assertEquals("Should return the immediate next sibling", p2, p1.nextElementSibling());
        assertEquals("Should return the immediate next sibling", p3, p2.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_LastElement() {
        Document doc = Parser.parseBodyFragment("<div><p>1</p><p>2</p></div>");
        Element p2 = doc.select("p").get(1);

        assertNull("Should return null when there is no next sibling", p2.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_SingleElement() {
        Document doc = Parser.parseBodyFragment("<div><p>1</p></div>");
        Element p1 = doc.select("p").get(0);

        assertNull("Should return null when only one child exists", p1.nextElementSibling());
    }

    @Test
    public void testNextElementSibling_FirstElement() {
        Document doc = Parser.parseBodyFragment("<div><p>1</p><p>2</p></div>");
        Element p1 = doc.select("p").get(0);
        Element p2 = doc.select("p").get(1);

        assertEquals("First element's next sibling should be the second element", p2, p1.nextElementSibling());
    }

    @Test(expected = NullPointerException.class)
    public void testNextElementSibling_NoParent() {
        // Creating an element not attached to a Document/Parent
        Element orphan = new Element(org.jsoup.parser.Tag.valueOf("div"), "");
        // This will trigger parent() returning null, and parent().children() throwing NPE 
        // or indexInList failing depending on internal implementation of parent()
        orphan.nextElementSibling();
    }
}
